def kth_smallest_positive_subarray_sum(nums, k):
    def at_least_k(limit):
        left = 0
        total = 0
        count = 0
        for right, value in enumerate(nums):
            total += value
            while total > limit:
                total -= nums[left]
                left += 1
            count += right - left + 1
        return count >= k
    left, right = min(nums), sum(nums)
    while left < right:
        middle = (left + right) // 2
        if at_least_k(middle):
            right = middle
        else:
            left = middle + 1
    return left

